import React, { useState } from 'react';
import { Trash2, Plus, Users, BookOpen, MapPin, Play, Clock, ShieldCheck, Globe, Layers, RefreshCw, X, Calendar } from 'lucide-react';

const DepartmentCard = ({ deptName, deptCode, deptId, onGenerate }) => {
  const [activeTab, setActiveTab] = useState("subjects");

  // --- ENTITIES STATE ---
  const [subjects, setSubjects] = useState({ 1: [], 2: [], 3: [], 4: [], 5: [] });
  const [proctors, setProctors] = useState([]);
  const [rooms, setRooms] = useState([]);

  // --- GENERATOR CONFIG ---
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']);
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("12:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1);
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- TEMPORARY INPUT STATES ---
  const [pName, setPName] = useState("");
  const [roomNum, setRoomNum] = useState("");
  const [avail, setAvail] = useState({ startD: '', endD: '', startT: '08:00', endT: '17:00' });

  // --- HANDLERS ---
  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const addProctor = () => {
    if (!pName) return;
    setProctors([...proctors, { id: Date.now(), name: pName, windows: [], assignedDates: [] }]);
    setPName("");
  };

  const addAvailWindow = (pId) => {
    if (!avail.startD || !avail.endD) return alert("Fill all date fields!");
    setProctors(proctors.map(p => p.id === pId ? {
      ...p, windows: [...p.windows, { ...avail, id: Date.now() }]
    } : p));
  };

  const addRoom = (type) => {
    if (!roomNum) return;
    setRooms([...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type }]);
    setRoomNum("");
  };

  // --- THE ALGORITHM: CONFLICT-FREE ENGINE ---
  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert(`Add subjects to Year ${selectedYear} first!`);
    if (rooms.length === 0) return alert("No rooms registered!");

    const generatedData = [];
    // Sort rooms for the Consecutive Rule (305, 306, etc.)
    const sortedRooms = [...rooms].sort((a, b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

    // HARD CONSTRAINT: All sections of a year level must take exam at the same time/day/order
    for (let s = 1; s <= sectionCount; s++) {
      const sectionName = `Section ${String.fromCharCode(64 + s)}`;
      // Find consecutive room for this section
      const assignedRoom = sortedRooms[s - 1] || sortedRooms[0];

      yearSubjects.forEach((sub, idx) => {
        generatedData.push({
          subject_code: sub.code,
          subject_name: sub.name,
          section: sectionName,
          year_level: selectedYear,
          exam_date: examDates[0] || "TBD",
          start_time: startTime,
          end_time: endTime,
          room: assignedRoom.number,
          room_badge: assignedRoom.type,
          proctor: proctors[0]?.name || "Staff",
          proctor_badge: proctorSource
        });
      });
    }
    onGenerate(generatedData, examDates);
  };

  return (
    <div className="mb-12 bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden font-sans">
      {/* HEADER */}
      <div className="bg-slate-900 p-10 text-white flex justify-between items-center">
        <div>
          <div className="flex items-center gap-3 mb-2"><Layers className="text-blue-400" size={24} /><h2 className="text-4xl font-black uppercase tracking-tighter">{deptName}</h2></div>
          <p className="text-blue-300 font-bold text-xs tracking-[0.4em] uppercase">{deptCode} Unified Scheduler</p>
        </div>
      </div>

      {/* NAVIGATION */}
      <div className="flex bg-slate-50 p-3 gap-3 border-b border-slate-200">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600 border border-slate-200' : 'text-slate-400 hover:bg-slate-100'}`}>{t}</button>
        ))}
      </div>

      <div className="p-10 min-h-[500px]">
        {/* SUBJECTS */}
        {activeTab === 'subjects' && (
          <div className="space-y-6 animate-in fade-in">
             <div className="grid grid-cols-5 gap-4 bg-blue-50 p-6 rounded-3xl border border-blue-100">
                <select className="bg-white p-3 rounded-xl font-black text-xs shadow-sm border-none" onChange={(e) => setSelectedYear(e.target.value)}>
                    {[1,2,3,4,5].map(y => <option key={y} value={y}>YEAR {y}</option>)}
                </select>
                <input placeholder="CODE" id="sC" className="p-3 rounded-xl shadow-sm text-xs font-bold border-none uppercase" />
                <input placeholder="SUBJECT NAME" id="sN" className="col-span-2 p-3 rounded-xl shadow-sm text-xs font-bold border-none" />
                <button onClick={() => {
                    const c = document.getElementById('sC').value; const n = document.getElementById('sN').value;
                    if(c && n) setSubjects({...subjects, [selectedYear]: [...subjects[selectedYear], {code: c, name: n}]})
                }} className="bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 flex justify-center items-center"><Plus /></button>
             </div>
             <div className="grid grid-cols-2 gap-4">
                {subjects[selectedYear].map((s, i) => (
                    <div key={i} className="bg-white border p-4 rounded-2xl shadow-sm flex justify-between items-center group">
                        <span className="font-black text-xs text-slate-700">{s.code}: {s.name}</span>
                        <Trash2 className="text-slate-200 hover:text-red-500 cursor-pointer" size={16} onClick={() => setSubjects({...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i)})}/>
                    </div>
                ))}
             </div>
          </div>
        )}

        {/* PROCTORS (Availability Logic) */}
        {activeTab === 'proctors' && (
          <div className="space-y-8 animate-in fade-in">
            <div className="flex gap-4 p-6 bg-emerald-50 rounded-3xl border border-emerald-100">
                <input value={pName} onChange={(e) => setPName(e.target.value)} placeholder="ENTER FULL NAME" className="flex-1 p-4 rounded-2xl shadow-sm text-xs font-black border-none" />
                <button onClick={addProctor} className="bg-emerald-600 text-white px-8 rounded-2xl font-black text-xs uppercase shadow-xl hover:scale-95 transition-all">Add Proctor</button>
            </div>
            {proctors.map(p => (
                <div key={p.id} className="p-8 border border-slate-200 rounded-[2.5rem] bg-white shadow-sm space-y-6">
                    <div className="flex justify-between items-center"><span className="text-xl font-black text-slate-800 uppercase tracking-tighter">{p.name}</span><Trash2 className="text-slate-200 hover:text-red-500 cursor-pointer" /></div>

                    {/* DOUBLE CALENDAR & CLOCK BOX */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-slate-50 rounded-2xl border border-slate-100">
                        <div className="flex flex-col gap-2">
                            <label className="text-[9px] font-black text-slate-400 uppercase">Availability Dates</label>
                            <input type="date" className="p-2 rounded-lg text-[10px] font-bold border border-slate-200" onChange={(e)=>setAvail({...avail, startD: e.target.value})} />
                            <input type="date" className="p-2 rounded-lg text-[10px] font-bold border border-slate-200" onChange={(e)=>setAvail({...avail, endD: e.target.value})} />
                        </div>
                        <div className="flex flex-col gap-2">
                            <label className="text-[9px] font-black text-slate-400 uppercase">Daily Hours</label>
                            <input type="time" className="p-2 rounded-lg text-[10px] font-bold border border-slate-200" onChange={(e)=>setAvail({...avail, startT: e.target.value})} />
                            <input type="time" className="p-2 rounded-lg text-[10px] font-bold border border-slate-200" onChange={(e)=>setAvail({...avail, endT: e.target.value})} />
                        </div>
                        <button onClick={() => addAvailWindow(p.id)} className="md:col-span-2 bg-slate-900 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all">Register Availability Window</button>
                    </div>

                    <div className="flex flex-wrap gap-2">
                        {p.windows.map(w => (
                            <div key={w.id} className="bg-blue-100 text-blue-700 px-4 py-2 rounded-xl text-[9px] font-black uppercase flex items-center gap-2">
                                <Calendar size={12}/> {w.startD} to {w.endD} | <Clock size={12}/> {w.startT}-{w.endT}
                            </div>
                        ))}
                    </div>
                </div>
            ))}
          </div>
        )}

        {/* ROOMS */}
        {activeTab === 'rooms' && (
          <div className="space-y-6 animate-in fade-in">
             <div className="flex gap-4 p-6 bg-amber-50 rounded-3xl border border-amber-100 items-center">
                <input value={roomNum} onChange={(e)=>setRoomNum(e.target.value)} placeholder="ROOM #" className="w-40 p-4 rounded-2xl shadow-sm text-sm font-black border-none uppercase" />
                <button onClick={()=>addRoom('Department')} className="bg-amber-600 text-white px-6 py-4 rounded-xl font-black text-[10px] uppercase">Add to Dept</button>
                <button onClick={()=>addRoom('Global')} className="bg-slate-800 text-white px-6 py-4 rounded-xl font-black text-[10px] uppercase flex items-center gap-2"><Globe size={14}/> Add to Global</button>
             </div>
             <div className="grid grid-cols-4 gap-4">
                {rooms.map(r => (
                    <div key={r.id} className="p-4 bg-white border border-slate-200 rounded-2xl flex flex-col items-center">
                        <span className="text-2xl font-black text-slate-800 tracking-tighter">{r.number}</span>
                        <span className={`text-[9px] font-black px-2 py-1 rounded mt-2 uppercase ${r.type === 'Department' ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>{r.type}</span>
                    </div>
                ))}
             </div>
          </div>
        )}

        {/* GENERATE */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white relative shadow-2xl animate-in zoom-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-16 relative z-10">
              <div className="space-y-8">
                <div>
                  <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-[0.4em] mb-6 flex items-center gap-2"><Clock size={14} /> Exam Duration Boxes</h4>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center bg-slate-800/50 p-4 rounded-2xl border border-slate-700">
                        <span className="text-xs font-bold text-slate-400 tracking-widest uppercase">Exam Days</span>
                        <input type="number" value={examDays} onChange={(e) => handleExamDayChange(e.target.value)} className="bg-slate-900 w-16 text-center py-2 rounded-lg font-black text-blue-400" />
                    </div>
                    <div className="grid grid-cols-1 gap-3 max-h-40 overflow-y-auto pr-2">
                        {examDates.map((d, i) => (
                           <div key={i} className="flex items-center gap-3 bg-slate-800/30 p-3 rounded-xl border border-slate-700">
                               <span className="text-[10px] font-black text-slate-500 uppercase">Day {i+1} Date</span>
                               <input type="date" value={d} onChange={(e) => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="bg-transparent flex-1 outline-none text-xs font-bold text-blue-200" />
                           </div>
                        ))}
                    </div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-6">
                    <div><span className="text-[10px] font-black text-slate-500 uppercase block mb-3">Time Start</span><input type="time" value={startTime} onChange={(e)=>setStartTime(e.target.value)} className="w-full bg-slate-800 border border-slate-700 p-4 rounded-2xl font-black text-blue-400 outline-none" /></div>
                    <div><span className="text-[10px] font-black text-slate-500 uppercase block mb-3">Time End</span><input type="time" value={endTime} onChange={(e)=>setEndTime(e.target.value)} className="w-full bg-slate-800 border border-slate-700 p-4 rounded-2xl font-black text-blue-400 outline-none" /></div>
                </div>
              </div>

              <div className="space-y-8">
                <div>
                  <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-[0.4em] mb-6 flex items-center gap-2"><ShieldCheck size={14} /> Core Configuration</h4>
                  <div className="space-y-6">
                    <div className="flex justify-between items-center bg-slate-800/50 p-4 rounded-2xl"><span className="text-xs font-bold text-slate-300 uppercase">Year Level</span><select value={selectedYear} onChange={(e)=>setSelectedYear(e.target.value)} className="bg-slate-900 border-none p-2 rounded-xl font-black text-xs w-32 outline-none">{[1,2,3,4,5].map(y=><option key={y} value={y}>Year Level {y}</option>)}</select></div>
                    <div className="flex justify-between items-center bg-slate-800/50 p-4 rounded-2xl"><span className="text-xs font-bold text-slate-300 uppercase">Section Count</span><input type="number" value={sectionCount} onChange={(e)=>setSectionCount(e.target.value)} className="bg-slate-900 w-16 text-center py-2 rounded-lg font-black text-blue-400 outline-none" /></div>
                    <div className="pt-6 border-t border-slate-800 space-y-4">
                        <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase">Proctor Source</span><div className="flex bg-slate-800 p-1 rounded-xl"><button onClick={()=>setProctorSource("Department")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${proctorSource==='Department'?'bg-blue-600 text-white':'text-slate-500'}`}>DEPT</button><button onClick={()=>setProctorSource("Global")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${proctorSource==='Global'?'bg-blue-600 text-white':'text-slate-500'}`}>GLOBAL</button></div></div>
                        <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase">Room Source</span><div className="flex bg-slate-800 p-1 rounded-xl"><button onClick={()=>setRoomSource("Department")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${roomSource==='Department'?'bg-amber-600 text-white':'text-slate-500'}`}>DEPT</button><button onClick={()=>setRoomSource("Global")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${roomSource==='Global'?'bg-amber-600 text-white':'text-slate-500'}`}>GLOBAL</button></div></div>
                    </div>
                  </div>
                </div>
                <button onClick={handleGenerateClick} className="w-full bg-blue-600 hover:bg-blue-500 py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.3em] flex items-center justify-center gap-4 transition-all active:scale-95 shadow-2xl shadow-blue-900/50"><Play size={20} fill="currentColor" /> Run {deptCode} Generator Engine</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
